            '& .nprogress-bar > div': {
              position: 'absolute',
              top: 0,
              height: 2,
              boxShadow: `${(theme.vars || theme).palette.primary.main} 1px 0 6px 1px`,
              borderRadius: '100%',
              animation: `${muiNProgressPulse} 2s ease-out 0s infinite`,
            },
            '& .nprogress-bar > div:first-of-type': {
